var i=[{title:`Wege zu messen`,text:`Ein neuer Lastrekord ist leicht zu erkennen, aber 10 kontrollierte Wiederholungen mit einem Gewicht, bei dem früher sieben möglich waren, sind ebenfalls Fortschritt. Bei Körpergewichtsübungen kannst du dich verbessern, indem du die Neigung eines Liegestützes senkst, mehr Bewegungsumfang hinzufügst oder von unterstützten zu freien Wiederholungen übergehst.`},{title:`Geschätzte und getestete Maximalwerte`,text:`Dein Einwiederholungsmaximum (1RM) ist die schwerste Last, die du mit akzeptabler Technik für eine Wiederholung heben kannst. Formeln können es aus leichteren Sätzen schätzen, aber die Schätzungen werden zwischen Übungen, bei höheren Wiederholungszahlen und zwischen Hebern weniger verlässlich. Anfänger brauchen keine Maximaltests, um Fortschritte zu verfolgen.`},{title:`Gleiches mit Gleichem vergleichen`,text:`Halte Griff, Tiefe, Tempo, Ausrüstung und Pause beim Vergleich von Einheiten ungefähr gleich. Eine schwerere partielle Kniebeuge ist nicht automatisch gleichwertig mit einer leichteren Kniebeuge im vollen Bewegungsumfang. Mehr Kontrolle, Selbstvertrauen oder Ausdauer bei gleicher Last zählt ebenfalls als Verbesserung, mit oder ohne neues Maximum.`},{title:`Beispiel`,text:`Ein Ruderzug geht mit derselben Kurzhantel und ähnlicher Technik von 3 × 8 auf 3 × 12. Du könntest dann eine kleine Laststeigerung versuchen und dich durch den Wiederholungsbereich wieder hocharbeiten.`},{title:`TrainUp nutzen`,text:`TrainUp schreibt keine Gewichte vor: Du wählst die Last selbst. Dein Plan gibt für jede Übung Sätze und Wiederholungen vor, und während des Trainings erfasst du die Wiederholungen, die du wirklich geschafft hast.`}];var t=[{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Praktische Hinweise des ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};